/* Pixel Kanban Board Styles */
:root {
  --bg: #1a1a2e;
  --surface: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --border: #2a2a4a;
  --pixel-size: 4px;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  background-image: 
    linear-gradient(45deg, var(--border) 25%, transparent 25%),
    linear-gradient(-45deg, var(--border) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--border) 75%),
    linear-gradient(-45deg, transparent 75%, var(--border) 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 20px;
}

.board {
  width: 100%;
  max-width: 1200px;
  background: var(--surface);
  border: var(--pixel-size) solid var(--border);
  padding: 20px;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.3);
}

.board-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: var(--pixel-size) solid var(--border);
}

.board-header h1 {
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--primary);
}

.add-card {
  display: flex;
  gap: 8px;
}

.add-card input {
  background: var(--bg);
  border: var(--pixel-size) solid var(--border);
  color: var(--text);
  font-family: var(--font);
  font-size: 1rem;
  padding: 8px 12px;
  width: 200px;
  outline: none;
}

.add-card input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

button {
  background: var(--primary);
  border: var(--pixel-size) solid var(--border);
  color: var(--text);
  font-family: var(--font);
  font-size: 1rem;
  padding: 8px 16px;
  cursor: pointer;
  transition: transform 0.1s, background 0.1s;
  text-transform: uppercase;
  letter-spacing: 1px;
}

button:hover {
  background: var(--accent);
  transform: translate(-2px, -2px);
  box-shadow: 2px 2px 0 var(--border);
}

button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  transform: translate(0, 0);
  box-shadow: none;
}

button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

.columns {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.column {
  background: var(--bg);
  border: var(--pixel-size) solid var(--border);
  padding: 12px;
  min-height: 200px;
  display: flex;
  flex-direction: column;
}

.column h2 {
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--accent);
}

.count {
  background: var(--primary);
  padding: 2px 8px;
  font-size: 0.9rem;
  border: 2px solid var(--border);
}

.card-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}

.card {
  background: var(--surface);
  border: 2px solid var(--border);
  padding: 8px 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  word-break: break-word;
}

.card-text {
  flex: 1;
  font-size: 0.95rem;
}

.card-actions {
  display: flex;
  gap: 4px;
}

.card-actions button {
  padding: 4px 8px;
  font-size: 0.85rem;
  min-width: 32px;
}

@media (max-width: 700px) {
  .columns {
    grid-template-columns: 1fr;
  }
  .board-header {
    flex-direction: column;
    align-items: stretch;
  }
  .add-card input {
    width: 100%;
  }
}

@media (max-width: 360px) {
  body {
    padding: 8px;
  }
  .board {
    padding: 12px;
  }
  .board-header h1 {
    font-size: 1.2rem;
  }
  .card-actions button {
    padding: 4px 6px;
    font-size: 0.75rem;
    min-width: 28px;
  }
}

// Pixel Kanban Board Logic
(function() {
  'use strict';

  const columns = ['todo', 'doing', 'done'];
  const lists = {
    todo: document.getElementById('todo-list'),
    doing: document.getElementById('doing-list'),
    done: document.getElementById('done-list')
  };
  const counts = {
    todo: document.getElementById('todo-count'),
    doing: document.getElementById('doing-count'),
    done: document.getElementById('done-count')
  };
  const input = document.getElementById('new-card-text');
  const addBtn = document.getElementById('add-card-btn');

  let cards = [];

  function createCard(text) {
    const id = Date.now() + Math.random().toString(36).slice(2, 7);
    return { id, text, column: 'todo' };
  }

  function render() {
    // Clear lists
    columns.forEach(col => {
      lists[col].innerHTML = '';
    });

    // Group cards by column
    const grouped = { todo: [], doing: [], done: [] };
    cards.forEach(card => {
      if (grouped[card.column]) grouped[card.column].push(card);
    });

    // Render each column
    columns.forEach(col => {
      const list = lists[col];
      grouped[col].forEach(card => {
        const cardEl = document.createElement('div');
        cardEl.className = 'card';
        cardEl.dataset.id = card.id;

        const textSpan = document.createElement('span');
        textSpan.className = 'card-text';
        textSpan.textContent = card.text;

        const actions = document.createElement('div');
        actions.className = 'card-actions';

        // Left button
        const leftBtn = document.createElement('button');
        leftBtn.textContent = '←';
        leftBtn.setAttribute('aria-label', 'Move card left');
        leftBtn.disabled = card.column === 'todo';
        leftBtn.addEventListener('click', () => moveCard(card.id, -1));

        // Right button
        const rightBtn = document.createElement('button');
        rightBtn.textContent = '→';
        rightBtn.setAttribute('aria-label', 'Move card right');
        rightBtn.disabled = card.column === 'done';
        rightBtn.addEventListener('click', () => moveCard(card.id, 1));

        // Delete button
        const delBtn = document.createElement('button');
        delBtn.textContent = '×';
        delBtn.setAttribute('aria-label', 'Delete card');
        delBtn.addEventListener('click', () => deleteCard(card.id));

        actions.appendChild(leftBtn);
        actions.appendChild(rightBtn);
        actions.appendChild(delBtn);

        cardEl.appendChild(textSpan);
        cardEl.appendChild(actions);
        list.appendChild(cardEl);
      });
      counts[col].textContent = grouped[col].length;
    });
  }

  function addCard() {
    const text = input.value.trim();
    if (!text) return;
    cards.push(createCard(text));
    input.value = '';
    input.focus();
    render();
  }

  function moveCard(id, direction) {
    const card = cards.find(c => c.id === id);
    if (!card) return;
    const idx = columns.indexOf(card.column);
    const newIdx = idx + direction;
    if (newIdx < 0 || newIdx >= columns.length) return;
    card.column = columns[newIdx];
    render();
  }

  function deleteCard(id) {
    cards = cards.filter(c => c.id !== id);
    render();
  }

  // Event listeners
  addBtn.addEventListener('click', addCard);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') addCard();
  });

  // Initial render
  render();
})();
